// Group an array of objects by `type`; each group is the array of the
// corresponding items' `n` values. Group order follows first appearance in
// the input, and values inside a group keep their original order.
export const solve = xs => {
  const groups = {};
  for (const { type, n } of xs) {
    if (Object.prototype.hasOwnProperty.call(groups, type)) {
      groups[type].push(n);
